package com.echo.pipeline;

import lombok.Builder;
import lombok.Getter;
import com.echo.service.Utf8ForwardBody;

import java.util.Map;

/**
 * Protocol-irrelevant response Value Object
 * <p>
 * The response information generated by encapsulating pipeline only exists during the execution of pipeline and is not persistent.
 */
@Getter
@Builder
public class MockResponse {

    /** HTTP status code, JMS fixed 200 */
    private final int status;

    /** response body */
    private final String body;

    /** Validated owned bytes, used only by the native HTTP forwarding adapter. */
    private final Utf8ForwardBody utf8Body;

    /** Preserve the text contract for callers that explicitly need the entire body. */
    public String getBody() {
        return utf8Body == null ? body : utf8Body.text();
    }

    /** HTTP response headers */
    private final Map<String, String> headers;

    /** Whether the match is successful */
    private final boolean matched;

    /** Is it a forwarding result? */
    private final boolean forwarded;

    /** The security display text of the actual downstream target must not contain the password or token */
    private final String forwardTarget;

    /** Forwarding error message */
    private final String proxyError;
}
